import * as rt from "../../../../build/dist/src/translate/runtime.js";

rt.type(6576, "/obj/item/weapon/paper/abductor", "/obj/item/weapon/paper", {
	name: "Dissection Guide",
	icon_state: "alienpaper_words",
	info: "<b>Dissection for Dummies</b><br>\n\n<br>\n 1.Acquire fresh specimen.<br>\n 2.Put the specimen on operating table.<br>\n 3.Apply surgical drapes, preparing for experimental dissection.<br>\n 4.Apply scalpel to specimen's torso.<br>\n 5.Clamp bleeders on specimen's torso with a hemostat.<br>\n 6.Retract skin of specimen's torso with a retractor.<br>\n 7.Apply scalpel again to specimen's torso.<br>\n 8.Search through the specimen's torso with your hands to remove any superfluous organs.<br>\n 9.Insert replacement gland (Retrieve one from gland storage).<br>\n 10.Consider dressing the specimen back to not disturb the habitat. <br>\n 11.Put the specimen in the experiment machinery.<br>\n 12.Choose one of the machine options. The target will be analyzed and teleported to the selected drop-off point.<br>\n 13.You will receive one supply credit, and the subject will be counted towards your quota.<br>\n<br>\nCongratulations! You are now trained for invasive xenobiology research!",
});
rt.type(6577, "/obj/item/weapon/paper/Cloning", "/obj/item/weapon/paper", {
	name: "paper - 'H-87 Cloning Apparatus Manual",
	info: "<h4>Getting Started</h4>\n\tCongratulations, your station has purchased the H-87 industrial cloning device!<br>\n\tUsing the H-87 is almost as simple as brain surgery! Simply insert the target humanoid into the scanning chamber and select the scan option to create a new profile!<br>\n\t<b>That's all there is to it!</b><br>\n\t<i>Notice, cloning system cannot scan inorganic life or small primates.  Scan may fail if subject has suffered extreme brain damage.</i><br>\n\t<p>Clone profiles may be viewed through the profiles menu. Scanning implants a complementary HEALTH MONITOR IMPLANT into the subject, which may be viewed from each profile.\n\tProfile Deletion has been restricted to [Station Head] level access.</p>\n\t<h4>Cloning from a profile</h4>\n\tCloning is as simple as pressing the CLONE option at the bottom of the desired profile.<br>\n\tPer your company's EMPLOYEE PRIVACY RIGHTS agreement, the H-87 has been blocked from cloning crewmembers while they are still alive.<br>\n\t<br>\n\t<p>The provided CLONEPOD SYSTEM will produce the desired clone.  Standard clone maturation times (With SPEEDCLONE technology) are roughly 90 seconds.\n\tThe cloning pod may be unlocked early with any [Medical Researcher] ID after initial maturation is complete.</p><br>\n\t<i>Please note that resulting clones may have a small DEVELOPMENTAL DEFECT as a result of genetic drift.</i><br>\n\t<h4>Profile Management</h4>\n\t<p>The H-87 (as well as your station's standard genetics machine) can accept STANDARD DATA DISKETTES.\n\tThese diskettes are used to transfer genetic information between machines and profiles.\n\tA load/save dialog will become available in each profile if a disk is inserted.</p><br>\n\t<i>A good diskette is a great way to counter aforementioned genetic drift!</i><br>\n\t<br>\n\t<font size=1>This technology produced under license from Thinktronic Systems, LTD.</font>",
});
rt.type(6578, "/obj/item/weapon/paper/recycler", "/obj/item/weapon/paper", {
	name: "paper - 'garbage duty instructions'",
	info: "<h2>New Assignment</h2> You have been assigned to collect garbage from trash bins, located around the station. The crewmembers will put their trash into it and you will collect the said trash.<br><br>There is a recycling machine near your closet, inside maintenance; use it to recycle the trash for a small chance to get useful minerals. Then deliver these minerals to cargo or engineering. You are our last hope for a clean station, do not screw this up!",
});
rt.type(6580, "/obj/item/weapon/paper/nuke_instructions", "/obj/item/weapon/paper", {
	info: "How to break into a Nanotrasen self-destruct terminal and remove its plutonium core:<br><ul><li>Use a screwdriver with a very thin tip (provided) to unscrew the terminal's front panel</li><li>Dislodge and remove the front panel with a crowbar</li><li>Cut the inner metal plate with a welding tool</li><li>Pry off the inner plate with a crowbar to expose the radioactive core</li><li>Use the core container to remove the plutonium core; the container will take some time to seal</li><li>???</li></ul>",
});
rt.type(6581, "/obj/item/weapon/paper/supermatter_sliver_instructions", "/obj/item/weapon/paper", {
	info: "How to safely extract a supermatter sliver:<br><ul><li>Approach an active supermatter crystal with proper protective gear. DO NOT MAKE PHYSICAL CONTACT.</li><li>Use a supermatter scalpel (provided) to slice off a sliver of the crystal.</li><li>Use supermatter extraction tongs (also provided) to safely remove the sliver.</li><li>Physical contact of any object with the sliver will dust the object, as well as yourself.</li><li>Use the tongs to place the sliver into the provided container, which will take some time to seal</li><li>Get the hell out before the crystal delaminates.</li><li>???</li></ul>",
});
rt.type(6582, "/obj/item/weapon/paper/morguereminder", "/obj/item/weapon/paper", {
	name: "morgue memo",
	info: "<font size='2'>Since this station's medbay never seems to fail to be staffed by the mindless monkeys meant for genetics experiments, I'm leaving a reminder here for anyone handling the pile of cadavers the quacks are sure to leave.</font><BR><BR><font size='4'><font color=red>Red lights mean there's a plain ol' dead body inside.</font><BR><BR><font color=orange>Yellow lights mean there's non-body objects inside.</font><BR><font size='2'>Probably stuff pried off a corpse someone grabbed, or if you're lucky it's stashed booze.</font><BR><BR><font color=green>Green lights mean the morgue system detects the body may be able to be cloned.</font></font><BR><font size='2'>I don't know how that works, but keep it away from the kitchen and go yell at the geneticists.</font><BR><BR>- Centcom medical inspector",
});
rt.type(6583, "/obj/item/weapon/paper/pamphlet", "/obj/item/weapon/paper", {
	name: "pamphlet",
	icon_state: "pamphlet",
	info: "<b>Welcome to the Nanotrasen Gateway project...</b><br>Congratulations! If you're reading this, you and your superiors have decided that you're ready to commit to a life spent colonising the rolling hills of far away worlds. You must be ready for a lifetime of adventure, a little bit of hard work, and an award winning dental plan- but that's not all the Nanotrasen Gateway project has to offer.<br><br>Because we care about you, we feel it is only fair to make sure you know the risks before you commit to joining the Nanotrasen Gateway project. All away destinations have been fully scanned by a Nanotrasen expeditionary team, and are certified to be 100% safe. We've even left a case of space beer along with the basic materials you'll need to expand Nanotrasen's operational area and start your new life.<br><br><b>Gateway Operation Basics</b><br>All Nanotrasen approved Gateways operate on the same basic principals. They operate off area equipment power as you would expect, and without this supply, it cannot safely function, causinng it to reject all attempts at operation.<br><br>Once it is correctly setup, and once it has enough power to operate, the Gateway will begin searching for an output location. The amount of time this takes is variable, but the Gateway interface will give you an estimate accurate to the minute. Power loss will not interrupt the searching process. Influenza will not interrupt the searching process. Temporal anomalies may cause the estimate to be inaccurate, but will not interrupt the searching process.<br><br> <b>Life On The Other Side</b><br>Once you have traversed the Gateway, you may experience some disorientation. Do not panic. This is a normal side effect of travelling vast distances in a short period of time. You should survey the immediate area, and attempt to locate your complimentary case of space beer. Our expeditionary teams have ensured the complete safety of all away locations, but in a small number of cases, the Gateway they have established may not be immediately obvious. Do not panic if you cannot locate the return Gateway. Begin colonisation of the destination. <br><br><b>A New World</b><br>As a participant in the Nanotrasen Gateway Project, you will be on the frontiers of space. Though complete safety is assured, participants are advised to prepare for inhospitable environs.",
});
rt.type(6584, "/obj/item/weapon/paper/pamphlet/ccaInfo", "/obj/item/weapon/paper/pamphlet", {
	name: "Visitor Info Pamphlet",
	info: "<b> XCC-P5831 Visitor Information </b><br>Greetings, visitor, to  XCC-P5831! As you may know, this outpost was once used as Nanotrasen's CENTRAL COMMAND STATION, organizing and coordinating company projects across the vastness of space. <br>Since the completion of the much more efficient CC-A5831 on March 8, 2553, XCC-P5831 no longer acts as NT's base of operations but still plays a very important role its corporate affairs; serving as a supply and repair depot, as well as being host to its most important legal proceedingsand the thrilling pay-per-view broadcasts of <i>PLASTEEL CHEF</i> and <i>THUNDERDOME LIVE</i>.<br> We hope you enjoy your stay!",
});
rt.type(6585, "/obj/item/weapon/paper/ccaMemo", "/obj/item/weapon/paper", {
	name: "Memo to XCC-P5831 QM",
	info: "<b>From: XCC-P5831 Management Office</b><br><b>To: Rolf Ingram, XCC-P5831 Quartermaster</b><br>Hey, Rolf, once you pack that gateway into the ferry hangar, <i>make absolutely sure</i> to deactivate it! As you may know, SS13 has recently got its network up and running, which means that until we get this gate shipped off to the next colonization staging area, they'll be able to hop straight in here if its hooked up on our end.<br>Obviously, that's something I'd very much rather avoid. Our forensics and medical teams never did figure out what happened that last time... and I can't wrap my head around it myself. Why would a shuttle full of evacuees all snap and beat each other to death the moment they reached safety?<br>- D. Cereza",
});
