rt.type(6587, "/obj/item/weapon/paper/crumpled/snowdin", "/obj/item/weapon/paper/crumpled", {});
rt.type(6588, "/obj/item/weapon/paper/crumpled/snowdin/snowdingatewaynotice", "/obj/item/weapon/paper/crumpled/snowdin", {
	name: "scribbled note",
	info: "The gateway has been inactive for months, engineers think it's due to the recent drop in tempature fucking with the\n\tcircuitry or something. Without a constant supply of resources from central command, our stock is getting awfully low. Some of the security members have taken to\n\tusing the sparse rifle ammo left to hunting some of the wildlife to try and keep our food supply from emptying. God forbid if the heating goes out, I don't want to\n\tdie as a fucking popsicle down here.",
});
rt.type(6589, "/obj/item/weapon/paper/crumpled/snowdin/misc1", "/obj/item/weapon/paper/crumpled/snowdin", {
	name: "Mission Prologue",
	info: "Holy shit, what a rush! Those Nanotrasen bastards didn't even know what hit 'em! All five of us dropped in right on the captain, didn't even have time to yell! We were in and out with that disk in mere minutes!\n\tCrew didn't even know what was happening till the delta alert went down and by then were were already gone. We got a case to drink on the way home to celebrate, fuckin' job well done!",
});
rt.type(6590, "/obj/item/weapon/paper/crumpled/snowdin/keys", "/obj/item/weapon/paper/crumpled/snowdin", {
	name: "scribbled note",
	info: "As a notice for anyone looking to borrow an ATV, some asshat lost the key set for all the vehicles. Nobody has yet to actually come forward about the potential where-abouts, either due to embarrassment or fear of\n\treprecussions. I hope they enjoy walking through that shit snow during the next shipment because I sure as hell ain't.",
});
rt.type(6591, "/obj/item/weapon/paper/crumpled/snowdin/syndielava", "/obj/item/weapon/paper/crumpled/snowdin", {
	name: "scribbled note",
	info: "Some cracks in the ice nearby have exposed some sort of hidden magma stream under all this shit ice. I don't know whats worse at this point honestly; freezing to death or\n\tburning alive.",
});
rt.type(6592, "/obj/item/weapon/paper/crumpled/snowdin/lootstructures", "/obj/item/weapon/paper/crumpled/snowdin", {
	name: "scribbled note",
	info: "From what we've seen so far, theres a ton of iced-over ruins down here in the caves. We sent a few men out to check things out and they never came back, so we decided to\n\tborder up majority of the ruins. We've heard some weird shit coming out of these caves and I'm not gonna find out the hard way myself.",
});
rt.type(6593, "/obj/item/weapon/paper/crumpled/snowdin/shovel", "/obj/item/weapon/paper/crumpled/snowdin", {
	name: "shoveling duties",
	info: "Snow piles up bad here all-year round, even worse during the winter months. Keeping a constant rotation of shoveling that shit out of the way of the airlocks and keeping the paths decently clear\n\tis a good step towards not getting stuck walking through knee-deep snow.",
});
